<?php

namespace App\Support;

/**
 * Logo de Main Industrial embebido (PNG en base64) para servirlo por una ruta de
 * Laravel, sin depender de un archivo estatico en el hosting.
 */
class BrandLogo
{
    public static function bytes(): string
    {
        return base64_decode(self::BASE64);
    }

    private const BASE64 = '';
}
